CREATE OR REPLACE FUNCTION public.pass4p_profile_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE subtype text;s text; changed boolean; BEGIN
 SELECT provider_subtype INTO subtype FROM public.workspaces WHERE id=NEW.workspace_id;
 changed:=TG_OP='INSERT'; IF TG_OP='UPDATE' THEN changed:=NEW.service_types IS DISTINCT FROM OLD.service_types OR NEW.medical_delivery IS DISTINCT FROM OLD.medical_delivery OR NEW.visible IS DISTINCT FROM OLD.visible; END IF;
 IF changed AND subtype='independent_contractor' AND (NEW.service_types && ARRAY['wheelchair','stretcher']::text[] OR NEW.medical_delivery) THEN RAISE EXCEPTION 'Independent Contractor supports Ambulatory only; wheelchair/stretcher require eligible NEMT business evidence'; END IF;
 IF changed AND NEW.visible THEN FOREACH s IN ARRAY NEW.service_types LOOP IF NOT public.pass4p_service_eligible(NEW.workspace_id,s) THEN RAISE EXCEPTION 'Vehicle and applicable platform evidence required before advertising'; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.pass4p_vehicle_evidence_invalidate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.make IS DISTINCT FROM OLD.make OR NEW.model IS DISTINCT FROM OLD.model OR NEW.model_year IS DISTINCT FROM OLD.model_year OR NEW.plate IS DISTINCT FROM OLD.plate OR NEW.vehicle_category IS DISTINCT FROM OLD.vehicle_category OR NEW.capacity IS DISTINCT FROM OLD.capacity OR NEW.wheelchair_capacity IS DISTINCT FROM OLD.wheelchair_capacity OR NEW.accessibility_equipment IS DISTINCT FROM OLD.accessibility_equipment OR NEW.service_capabilities IS DISTINCT FROM OLD.service_capabilities OR NEW.insurance_doc_path IS DISTINCT FROM OLD.insurance_doc_path THEN NEW.evidence_status:='under_review'; END IF; RETURN NEW; END $$;
CREATE TRIGGER z_pass4p_vehicle_evidence_invalidate BEFORE UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.pass4p_vehicle_evidence_invalidate();
CREATE FUNCTION public.pass4p_vehicle_complete(_v uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.vehicles v WHERE v.id=_v AND v.vehicle_category IS NOT NULL AND nullif(trim(v.make),'') IS NOT NULL AND nullif(trim(v.model),'') IS NOT NULL AND v.model_year BETWEEN 1900 AND extract(year FROM current_date)::integer+1 AND nullif(trim(v.plate),'') IS NOT NULL AND v.capacity>0 AND v.status='active' AND cardinality(v.service_capabilities)>0 AND (NOT ('wheelchair'=ANY(v.service_capabilities)) OR (v.vehicle_category='wheelchair' AND v.wheelchair_capacity>0 AND nullif(trim(v.accessibility_equipment),'') IS NOT NULL))) $$;
REVOKE ALL ON FUNCTION public.pass4p_vehicle_complete(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pass4p_vehicle_complete(uuid) TO authenticated,service_role;
CREATE FUNCTION public.pass4p_document_present(_ws uuid,_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.provider_credentials c JOIN storage.objects o ON o.bucket_id='provider-docs' AND o.name=c.doc_path JOIN storage.buckets b ON b.id=o.bucket_id AND NOT b.public JOIN public.workspace_members m ON m.user_id=c.provider_user_id AND m.workspace_id=c.workspace_id AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL WHERE c.workspace_id=_ws AND c.kind=_kind AND c.accuracy_attested_at IS NOT NULL AND c.lifecycle_state='current' AND c.effective_at<=current_date AND c.expires_at>=current_date AND c.doc_path LIKE 'credentials/'||c.provider_user_id::text||'/%' AND (_kind<>'auto_insurance' OR (nullif(c.insurance_carrier,'') IS NOT NULL AND nullif(c.policy_reference,'') IS NOT NULL AND c.coverage_cents>0))) $$;
REVOKE ALL ON FUNCTION public.pass4p_document_present(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pass4p_document_present(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.pass4p_service_eligible(_ws uuid,_service text,_vehicle uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=_ws AND w.status='active' AND NOT w.is_test_account AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=w.id AND (_vehicle IS NULL OR v.id=_vehicle) AND v.status='active' AND v.vehicle_category IS NOT NULL AND lower(_service)=ANY(v.service_capabilities) AND v.capacity>0 AND (lower(_service)<>'wheelchair' OR v.wheelchair_capacity>0) AND (w.provider_subtype='nemt_business' OR (lower(_service)='ambulatory' AND v.vehicle_category='ambulatory' AND public.pass4p_vehicle_complete(v.id) AND v.evidence_status='satisfied')))
 AND (w.provider_subtype='nemt_business' OR (lower(_service)='ambulatory' AND w.provider_verified AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['driver_license','auto_insurance','w9']) k WHERE NOT public.pass4p_document_present(w.id,k))))) $$;
COMMENT ON FUNCTION public.pass4p_service_eligible(uuid,text,uuid) IS 'No self approval: contractor vehicle attestation and existing platform approval plus current private documents; no insurance sufficiency inferred from upload.';